/**
 * Audio assets (generated by scripts/audio/generate_audio.py and bundled in
 * public/audio, so nothing is fetched from other servers) and how loud each
 * one plays relative to the sound-effects volume.
 */
export type SfxName = 'click' | 'cash' | 'buy' | 'coins' | 'error' | 'unlock' | 'dayStart' | 'dayEnd' | 'lowStock';

export const SFX: Record<SfxName, { file: string; gain: number; minGap: number }> = {
  // minGap (seconds): the same effect never stacks faster than this.
  click: { file: 'click.wav', gain: 0.35, minGap: 0.04 },
  cash: { file: 'cash.wav', gain: 0.42, minGap: 0.08 },
  buy: { file: 'buy.wav', gain: 0.45, minGap: 0.08 },
  coins: { file: 'coins.wav', gain: 0.45, minGap: 0.15 },
  error: { file: 'error.wav', gain: 0.4, minGap: 0.2 },
  unlock: { file: 'unlock.wav', gain: 0.45, minGap: 0.5 },
  dayStart: { file: 'day-start.wav', gain: 0.4, minGap: 1 },
  dayEnd: { file: 'day-end.wav', gain: 0.45, minGap: 1 },
  lowStock: { file: 'low-stock.wav', gain: 0.35, minGap: 2 },
};

/** "Teh Sore": 24 bars at 84 BPM. The file holds this loop plus a 4 s tail. */
export const MUSIC = { file: 'music-teh-sore.mp3', loopSeconds: (24 * 4 * 60) / 84, fadeIn: 2.5 };

/** Music level while the pause menu is open, per the "Musik saat jeda" setting. */
export const PAUSE_MUSIC_LEVEL = { normal: 1, soft: 0.4, off: 0 } as const;

/** Files live next to index.html (public/audio), so resolve against the page itself. */
export function audioUrl(file: string): string {
  return new URL(`audio/${file}`, document.baseURI).href;
}
